// Three Powers — worker unico, sem pastas.
// O app inteiro vive aqui dentro. A chave da Anthropic fica na variavel
// de ambiente ANTHROPIC_API_KEY e nunca chega ao navegador.

// Modelo por tipo de tarefa. Avaliar e comparacao estruturada e roda bem no barato.
// Gerar exige mais qualidade, entao usa o modelo melhor. Ambos podem ser trocados
// por variavel de ambiente no painel do Worker, sem mexer no codigo.
const MODELO = {
  avaliar: 'claude-haiku-4-5-20251001',
  gerar:   'claude-sonnet-5'
};
const MAX_PROMPT = 8000;

